import React, { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { trpc } from "@/lib/trpc";
import { Input } from "@/components/ui/input";
import { safeReturnTo } from "@/const";

const LOGO_SRC =
  "data:image/png;base64,";

function useGoogleFonts() {
  useEffect(() => {
    const id = "gc-login-fonts";
    if (document.getElementById(id)) return;
    const link = document.createElement("link");
    link.id = id;
    link.rel = "stylesheet";
    link.href =
      "https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Inter:wght@400;500;600;700&display=swap";
    document.head.appendChild(link);
  }, []);
}

export default function LoginPage() {
  const [employeeId, setEmployeeId] = useState("");
  const [password, setPassword] = useState("");
  const login = trpc.auth.login.useMutation({ onSuccess: () => {
    const current = `${window.location.pathname}${window.location.search}`;
    window.location.assign(window.location.pathname === "/login" ? safeReturnTo(new URLSearchParams(window.location.search).get("returnTo")) : current);
  } });
  const loading = login.isPending;
  const [mounted, setMounted] = useState(false);
  useGoogleFonts();

  useEffect(() => {
    const t = setTimeout(() => setMounted(true), 40);
    return () => clearTimeout(t);
  }, []);

  const handleLogin = (event: React.FormEvent) => {
    event.preventDefault();
    login.mutate({ employeeId, password });
  };

  return (
    <main
      className="flex min-h-screen w-full bg-[#FBFAF8]"
      style={{ fontFamily: "Inter, system-ui, sans-serif" }}
    >
      {/* Brand panel */}
      <section
        className="relative hidden w-[45%] flex-col justify-between overflow-hidden px-14 py-12 lg:flex"
        style={{
          background:
            "radial-gradient(120% 140% at 8% 0%, #22171A 0%, #14171B 42%, #0E1013 100%)",
        }}
      >
        {/* ambient glow behind logo */}
        <div
          className="pointer-events-none absolute -left-16 -top-24 h-72 w-72 rounded-full opacity-40"
          style={{
            background:
              "radial-gradient(closest-side, rgba(236,27,35,0.35), transparent)",
            filter: "blur(10px)",
          }}
          aria-hidden="true"
        />

        {/* speed-mark accent, echoing the wordmark strokes */}
        <svg
          className="pointer-events-none absolute -bottom-20 -right-10 h-[380px] w-[380px] opacity-[0.5]"
          viewBox="0 0 400 400"
          aria-hidden="true"
        >
          <defs>
            <linearGradient id="strokeFade" x1="0" y1="1" x2="1" y2="0">
              <stop offset="0%" stopColor="#EC1B23" stopOpacity="0" />
              <stop offset="100%" stopColor="#EC1B23" stopOpacity="0.55" />
            </linearGradient>
          </defs>
          <g stroke="url(#strokeFade)" strokeWidth="10" strokeLinecap="round">
            <line x1="40" y1="360" x2="220" y2="40" />
            <line x1="90" y1="380" x2="270" y2="60" />
            <line x1="140" y1="400" x2="320" y2="80" />
          </g>
        </svg>

        <img
          src={LOGO_SRC}
          alt="CKA Birla Group | IIMS"
          className="relative h-9 w-auto self-start drop-shadow-[0_0_24px_rgba(0,0,0,0.35)]"
        />

        <div className="relative max-w-sm">
          <p className="text-[13px] font-medium tracking-wide text-[#F0625E]">
            AssetTrack workspace
          </p>
          <h1
            className="mt-4 text-[34px] leading-[1.18] text-white"
            style={{ fontFamily: "Fraunces, Georgia, serif", fontWeight: 500 }}
          >
            Asset intelligence,
            <br />
            in one place.
          </h1>
          <p className="mt-5 text-[15px] leading-relaxed text-white/55">
            AssetTrack brings inventory, audits, and reporting for the IIMS into a single workspace.
          </p>

          <div className="mt-8 h-px w-12 bg-white/15" />
          <p className="mt-6 text-[13px] leading-relaxed text-white/35">
            Used every day for asset tracking and month-end reporting
          </p>
        </div>

        <p className="relative text-[13px] text-white/30">
          © {new Date().getFullYear()} CKA Birla Group. All rights reserved.
        </p>
      </section>

      {/* Sign-in panel */}
      <section className="flex flex-1 items-center justify-center px-6 py-16 sm:px-10">
        <div
          className={`w-full max-w-[400px] transition-all duration-700 ease-out ${
            mounted ? "translate-y-0 opacity-100" : "translate-y-3 opacity-0"
          }`}
        >
          {/* Logo shown only when the brand panel is hidden (mobile) */}
          <div
            className="mb-10 inline-flex rounded-lg px-3 py-2 lg:hidden"
            style={{ background: "#14171B" }}
          >
            <img src={LOGO_SRC} alt="CKA Birla Group | IIMS" className="h-6 w-auto" />
          </div>

          <p className="text-[13px] font-medium tracking-wide text-[#C5161D]">
            AssetTrack workspace
          </p>
          <h2 className="mt-3 text-[27px] font-semibold tracking-[-0.01em] text-[#171A1F]">
            Sign in to continue
          </h2>
          <p className="mt-3 text-[15px] leading-relaxed text-[#6B7280]">
            Use your Employee ID and password to access your asset-management workspace.
          </p>

          <form onSubmit={handleLogin} className="mt-6 space-y-4">
            <label className="block text-sm font-semibold text-[#171A1F]">Employee ID<Input className="mt-2 rounded-xl" autoComplete="username" required maxLength={80} value={employeeId} onChange={event => setEmployeeId(event.target.value)} /></label>
            <label className="block text-sm font-semibold text-[#171A1F]">Password<Input className="mt-2 rounded-xl" type="password" autoComplete="current-password" required maxLength={128} value={password} onChange={event => setPassword(event.target.value)} /></label>
            {login.error && <p role="alert" className="text-sm text-red-700">{login.error.message}</p>}
          <Button
            type="submit"
            disabled={loading}
            className="group mt-9 flex h-[52px] w-full items-center justify-center gap-3 rounded-xl bg-[#171A1F] text-[15px] font-medium text-white shadow-[0_1px_2px_rgba(23,26,31,0.06)] transition-all duration-200 ease-out hover:-translate-y-[1px] hover:bg-[#1F2329] hover:shadow-[0_10px_24px_-6px_rgba(236,27,35,0.35)] focus-visible:ring-2 focus-visible:ring-[#EC1B23] focus-visible:ring-offset-2 disabled:opacity-70"
          >
            {loading ? "Signing in..." : "Sign in"}
          </Button>
          </form>

          <div className="mt-6 flex items-start gap-2.5">
            <svg
              viewBox="0 0 20 20"
              className="mt-[2px] h-4 w-4 shrink-0 text-[#B3B8C0]"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.6"
              aria-hidden="true"
            >
              <circle cx="10" cy="10" r="7.25" />
              <path d="M10 8.5v5" strokeLinecap="round" />
              <circle cx="10" cy="6.3" r="0.9" fill="currentColor" stroke="none" />
            </svg>
            <p className="text-[13px] leading-relaxed text-[#8A9099]">
              Access is limited to invited team members. Contact your
              workspace admin if you can't sign in.
            </p>
          </div>

          <div className="mt-14 flex items-center justify-between border-t border-[#EDEBE7] pt-6">
            <p className="text-[13px] text-[#B3B8C0] lg:hidden">
              © {new Date().getFullYear()} CKA Birla Group
            </p>
            <a
              href="#"
              className="ml-auto text-[13px] font-medium text-[#6B7280] underline decoration-[#D8D5CF] underline-offset-4 transition-colors hover:text-[#171A1F] hover:decoration-[#171A1F]"
            >
              Need help signing in?
            </a>
          </div>
        </div>
      </section>
    </main>
  );
}
